package vn.lutrinh.app.catalog

import okhttp3.mockwebserver.Dispatcher
import okhttp3.mockwebserver.MockResponse
import okhttp3.mockwebserver.RecordedRequest
import org.json.JSONArray
import org.json.JSONObject
import java.util.Collections

/**
 * The spec sample served by a MockWebServer as the public API v1 does (lutrinh-server
 * spec/README "Public API /api/v1"). The sample's media hashes are synthetic, so each file gets
 * generated bytes and the media entries + size.media are rewritten to match them.
 */
class ServedSample(val code: String = "HG4N7KQE", arrivalNotes: Map<Int, String> = emptyMap()) : Dispatcher() {
    val doc: JSONObject = Spec.json(Spec.SAMPLE)

    /** sha256 → file bytes. */
    val files = LinkedHashMap<String, ByteArray>()

    init {
        // R41: leg notes (stop index → note) the shared sample does not carry yet.
        arrivalNotes.forEach { (i, note) -> doc.getJSONArray("stops").getJSONObject(i).put("arrivalNote", note) }
        val media = doc.getJSONArray("media")
        var total = 0L
        for (i in 0 until media.length()) {
            val m = media.getJSONObject(i)
            val body = ("lutrinh-test:" + m.getString("id") + ":").repeat(150 + 23 * i).toByteArray()
            val sha = PackageJson.sha256(body)
            m.put("sha256", sha).put("bytes", body.size)
            files[sha] = body
            total += body.size
        }
        doc.getJSONObject("size").put("media", total)
    }

    val routeBytes: ByteArray = doc.toString().toByteArray()

    /** Tokens the server accepts now; [lookUp] issues `tk_<n>`. */
    val validTokens: MutableSet<String> = Collections.synchronizedSet(HashSet())
    private var issued = 0

    /** Called before every media answer (index of the answer, 0-based); may revoke tokens. */
    @Volatile var beforeMedia: (Int) -> Unit = {}
    @Volatile var corrupt: Set<String> = emptySet()
    @Volatile var corruptTimes = Int.MAX_VALUE
    private var mediaAnswers = 0
    private val corrupted = HashMap<String, Int>()

    /** Answers to give instead of the normal one (path prefix → response), for the error table. */
    val overrides = LinkedHashMap<String, MockResponse>()

    val requests: MutableList<RecordedRequest> = Collections.synchronizedList(ArrayList())

    @Synchronized
    override fun dispatch(request: RecordedRequest): MockResponse {
        requests += request
        val path = request.path!!.substringBefore('?')
        overrides.entries.firstOrNull { path.startsWith(it.key) }?.let { return it.value }
        return when {
            path == "/api/v1/meta" -> json(JSONObject().put("formatVersions", JSONArray().put(1)).put("maintenance", false).put("message", JSONObject.NULL))
            path.startsWith("/api/v1/codes/") -> {
                val asked = path.removePrefix("/api/v1/codes/").replace("-", "")
                if (asked != code) error(404, "code_not_found") else json(summary("tk_${++issued}".also { validTokens += it }))
            }
            path.startsWith("/api/v1/dl/") -> {
                val rest = path.removePrefix("/api/v1/dl/")
                val token = rest.substringBefore('/')
                if (token !in validTokens) return error(401, "token_expired")
                val what = rest.substringAfter('/')
                if (what == "route") {
                    MockResponse().setBody(okio.Buffer().write(routeBytes)).setHeader("Content-Type", "application/vnd.lutrinh.route+json;v=1")
                } else {
                    beforeMedia(mediaAnswers++)
                    if (token !in validTokens) return error(401, "token_expired")
                    val sha = what.removePrefix("media/")
                    var body = files[sha] ?: return error(404, "not_found")
                    if (sha in corrupt && (corrupted[sha] ?: 0) < corruptTimes) {
                        corrupted[sha] = (corrupted[sha] ?: 0) + 1
                        body = body.copyOf().also { it[0] = (it[0] + 1).toByte() }
                    }
                    val range = request.getHeader("Range")?.removePrefix("bytes=")?.substringBefore('-')?.toIntOrNull()
                    if (range != null) {
                        MockResponse().setResponseCode(206).setHeader("Content-Range", "bytes $range-${body.size - 1}/${body.size}")
                            .setBody(okio.Buffer().write(body, range, body.size - range))
                    } else {
                        MockResponse().setBody(okio.Buffer().write(body))
                    }
                }
            }
            else -> error(404, "not_found")
        }
    }

    fun summary(token: String): JSONObject {
        val route = doc.getJSONObject("route")
        val media = doc.getJSONArray("media")
        val legs = doc.getJSONArray("legs")
        val videos = (0 until media.length()).count { media.getJSONObject(it).getString("type") == "video" }
        return JSONObject()
            .put("code", code.substring(0, 4) + "-" + code.substring(4))
            .put("routeId", route.getString("id"))
            .put("version", route.getInt("version"))
            .put("formatVersion", 1)
            .put("title", route.getString("title"))
            .put("description", route.getString("description"))
            .put("days", route.getInt("days"))
            .put("stops", doc.getJSONArray("stops").length())
            .put("distanceM", (0 until legs.length()).sumOf { legs.getJSONObject(it).getDouble("distanceM") })
            .put("photos", media.length() - videos)
            .put("videos", videos)
            .put("bytes", doc.getJSONObject("size").getLong("media"))
            .put("files", doc.getJSONObject("size").getInt("files"))
            .put("region", route.getJSONObject("region"))
            .put("overview", legs.getJSONObject(0).getString("path"))
            .put("cover", JSONObject.NULL)
            .put("downloadToken", token)
            .put("tokenExpiresAt", "2026-11-20T05:00:00Z")
    }

    companion object {
        fun json(o: Any): MockResponse = MockResponse().setHeader("Content-Type", "application/json").setBody(o.toString())

        fun error(status: Int, code: String, retryAfterS: Int? = null): MockResponse {
            val err = JSONObject().put("code", code).put("retryAfterS", retryAfterS ?: JSONObject.NULL)
            return json(JSONObject().put("error", err)).setResponseCode(status).apply {
                if (retryAfterS != null) setHeader("Retry-After", retryAfterS.toString())
            }
        }
    }
}
